def group_(x2y, /):
    M = len(x2y)
    y2xs = [[] for x in range(M)]
    for x in range(M):
        y = x2y[x]
        y2xs[y].append(x)
    y2xs
    x2min_root = {}
    x2height = {}
    min_root2len_period = {}
    for x in range(M):
        if x in x2min_root:continue
        xs = [x]
        x2j = {x:0}
        for j in range(1,1+M):
            x = x2y[x]
            if x in x2min_root:break
            if x in x2j:break
            xs.append(x)
            x2j[x] = j
        else:
            raise Exception((M, xs[0]))
        x
        if x in x2min_root:
            min_root = x2min_root[x]
            height = x2height[x]
            extra = xs
            for x in xs:
                x2min_root[x] = min_root
            for height, x in enumerate(reversed(extra), 1+height):
                x2height[x] = height
            continue
        j = x2j[x]
        period = xs[j:]
        extra = xs[:j]
        min_root = min(period)
        min_root2len_period[min_root] = len(period)
        for x in xs:
            x2min_root[x] = min_root
        height = 0
        for x in period:
            x2height[x] = height
        for height, x in enumerate(reversed(extra), 1+height):
            x2height[x] = height
    x2min_root = [x2min_root[x] for x in range(M)]
    x2height = [x2height[x] for x in range(M)]
    y2num_xs = [*map(len, y2xs)]
    return (y2num_xs, y2xs, x2min_root, x2height, min_root2len_period)

def h(M, a, /):
    if M > 2**16:raise 000
    x2y = [None]*M
    for x in range(M):
        y = f(M,a,x)
        x2y[x] = y
    x2y
    (y2num_xs, y2xs, x2min_root, x2height, min_root2len_period) = group_(x2y)
    return (x2y, y2num_xs, y2xs, x2min_root, x2height, min_root2len_period)



