if 0:
  def group_(x2y, /):
    M = len(x2y)
    y2xs = [[] for x in range(M)]
    for x in range(M):
        y = x2y[x]
        y2xs[y].append(x)
    y2xs
    x2min_root = {}
    x2height = {}
    min_root2len_period = {}
    for x in range(M):
        if x in x2min_root:continue
        xs = [x]
        x2j = {x:0}
        for j in range(1,1+M):
            x = x2y[x]
            if x in x2min_root:break
            if x in x2j:break
            xs.append(x)
            x2j[x] = j
        else:
            raise Exception((M, xs[0]))
        x
        if x in x2min_root:
            min_root = x2min_root[x]
            height = x2height[x]
            extra = xs
            for x in xs:
                x2min_root[x] = min_root
            for height, x in enumerate(reversed(extra), 1+height):
                x2height[x] = height
            continue
        j = x2j[x]
        period = xs[j:]
        extra = xs[:j]
        min_root = min(period)
        min_root2len_period[min_root] = len(period)
        for x in xs:
            x2min_root[x] = min_root
        height = 0
        for x in period:
            x2height[x] = height
        for height, x in enumerate(reversed(extra), 1+height):
            x2height[x] = height
    x2min_root = [x2min_root[x] for x in range(M)]
    x2height = [x2height[x] for x in range(M)]
    y2num_xs = [*map(len, y2xs)]

    min_root2minmax_height = dict.fromkeys(min_root2len_period.keys(), (1+M, -1))
    for y, num_xs in enumerate(y2num_xs):
        if num_xs == 0:
            height = x2height[y]
            min_root = x2min_root[y]
            a, b = min_root2minmax_height[min_root]
            if b == -1:
                a = b = height
            elif height > b:
                assert a <= b < height
                b = height
            elif height < a:
                assert height < a <= b
                a = height
            else:
                assert a <= height <= b
                continue
            min_root2minmax_height[min_root] = (a, b)

    max_height = max(ht for _, ht in min_root2minmax_height.values())
    max_len_period = max(min_root2len_period.values())
    num_trees = len(min_root2len_period)
    return (y2num_xs, y2xs, x2min_root, x2height, min_root2len_period, min_root2minmax_height, (num_trees, max_len_period, max_height))

if 0:
  def tab_(f, M, /, *args):
    if M > 2**17:raise 000
    x2y = [None]*M
    for x in range(M):
        y = f(M, *args, x)
        x2y[x] = y
    x2y
    (y2num_xs, y2xs, x2min_root, x2height, min_root2len_period, min_root2minmax_height, (num_trees, max_len_period, max_height)) = group_(x2y)
    return (x2y, y2num_xs, y2xs, x2min_root, x2height, min_root2len_period, min_root2minmax_height, (num_trees, max_len_period, max_height))

def kMa2f_args_(k, M, a, /, *, ver=1):
    match ver:
        case 1:
            def f(M, a, k, vk, x, /):
                # [x1 =[%M]= x0*((1+vk) -a*vk*x0**k)]
                return x*((1+vk) -a*vk*pow(x, k, M)) %M
            vk = pow(k, -1, M)
            args = (a, k, vk)
        case -6669:
            #多设置几个驻点
            # [ver:=-6669] => [a值影响结果！]
            # 感觉无用
            assert k == 1
            def f(M, a, x, /):
                #return x*(2 -a*x) %M
                d = (1-a*x)
                ds = range(d, d+7*a, a)
                assert len(ds)&1 == 1 #附加部分数量是偶数
                return x*(1 +II_mod(M, ds)) %M
            args = (a,)
        case -6660:
            #多设置几个驻点
            # 环短树高，感觉无用
            assert k == 1
            step = a*(M//M.bit_length())
            sz = (M.bit_length() | 1)*step
            def f(M, a, sz, step, x, /):
                d = (1-a*x)
                ds = range(d, d+sz, step)
                assert len(ds)&1 == 1 #附加部分数量是偶数
                return x*(1 +II_mod(M, ds)) %M
            args = (a, sz, step)
        case -6661:
            #多设置几个驻点&&令[a值不重要]
            # [x1 == x0*(1+II[(1-a*(x0+u)) | [u:<-us]])]
            # [t*x1 == t*x0*(1+II[(1-(a/t)*(t*x0+t*u)) | [u:<-us]])]
            # => [us .* t == us]
            # [0 !<- us] => [len(us)%order_mod_(M;t) == 0]
            # [0 !<- us][len(us) > 0] => 然而t本来就是任选:[len(us) == phi(M)]
            #   不可行！
            raise 000
        case _:
            raise Exception(ver)

    return (f, args)
