def div2_mod_odd_(M, x, /):
    if x&1:
        x += M
    assert x&1 == 0
    x >>= 1
    x %= M
    return x

def div3_mod_(M, r3_M, x, /):
    assert r3_M
    x0 = x
    r3_x = x%3
    if r3_x:
        x += M << (r3_x == r3_M)
    x //= 3
    x %= M
    assert (x0 - 3*x)%M == 0
    return x



